require __DIR__ . '/app.php';

if (empty($config['installed'])) { header('Location: /install.php'); exit; }

$path = trim((string)parse_url($_SERVER['REQUEST_URI'] ?? '/', PHP_URL_PATH), '/');
$method = $_SERVER['REQUEST_METHOD'] ?? 'GET';

if ($method === 'POST') {
    if ($path === 'cart/add') {
        verify_csrf(); $id = (int)($_POST['product_id'] ?? 0);
        $stmt = db()->prepare('SELECT id, stock, active FROM products WHERE id = ?'); $stmt->execute([$id]); $p = $stmt->fetch();
        if (!$p || !$p['active'] || (int)$p['stock'] < 1) { flash('error', 'هذا المنتج غير متاح للطلب حالياً.'); redirect('/shop'); }
        $_SESSION['cart'][$id] = min((int)($p['stock']), max(1, (int)($_SESSION['cart'][$id] ?? 0) + 1));
        flash('success', 'أُضيف المنتج إلى السلة.'); redirect($_SERVER['HTTP_REFERER'] ?? '/cart');
    }
    if ($path === 'cart/update') {
        verify_csrf(); $quantities = $_POST['qty'] ?? [];
        foreach ($quantities as $id => $qty) { $id = (int)$id; $qty = (int)$qty; if ($qty <= 0) unset($_SESSION['cart'][$id]); else $_SESSION['cart'][$id] = min(20, $qty); }
        flash('success', 'تم تحديث السلة.'); redirect('/cart');
    }
    if ($path === 'cart/remove') { verify_csrf(); unset($_SESSION['cart'][(int)($_POST['product_id'] ?? 0)]); flash('success', 'تم حذف المنتج من السلة.'); redirect('/cart'); }
    if ($path === 'checkout') {
        verify_csrf(); $items = cart_rows();
        $name = trim((string)($_POST['customer_name'] ?? '')); $phone = trim((string)($_POST['phone'] ?? '')); $address = trim((string)($_POST['address'] ?? '')); $area = (string)($_POST['delivery_area'] ?? 'inside_city'); $note = trim((string)($_POST['note'] ?? ''));
        if (!$items || mb_strlen($name) < 2 || !preg_match('/^[0-9+\-\s]{8,20}$/', $phone) || mb_strlen($address) < 8) { flash('error', 'أدخل الاسم ورقم هاتف صالحاً وعنواناً كاملاً للتوصيل.'); redirect('/checkout'); }
        $pdo = db(); $pdo->beginTransaction();
        try { $subtotal = cart_total($items); $delivery = $area === 'outside_city' ? (float)setting('outside_city_delivery', '0') : (float)setting('delivery_charge', '0'); $payment = 'cash_on_delivery'; $note = '[Delivery zone: ' . ($area === 'outside_city' ? 'خارج المدينة' : 'داخل المدينة') . '] ' . $note; $total = $subtotal + $delivery; $code = order_code();
            $stmt = $pdo->prepare('INSERT INTO orders (order_code, customer_name, phone, address, note, subtotal, delivery_charge, total, payment_method, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)');
            $stmt->execute([$code, $name, $phone, $address, $note, $subtotal, $delivery, $total, $payment, 'new']); $orderId = (int)$pdo->lastInsertId();
            $line = $pdo->prepare('INSERT INTO order_items (order_id, product_id, product_name, unit_price, quantity, line_total) VALUES (?, ?, ?, ?, ?, ?)'); $stock = $pdo->prepare('UPDATE products SET stock = stock - ? WHERE id = ? AND stock >= ?');
            foreach ($items as $item) { $stock->execute([$item['quantity'], $item['id'], $item['quantity']]); if ($stock->rowCount() !== 1) throw new RuntimeException('تغيّرت كمية مخزون أحد المنتجات.'); $line->execute([$orderId, $item['id'], $item['name'], $item['unit_price'], $item['quantity'], $item['line_total']]); }
            $pdo->commit(); $_SESSION['cart'] = []; $_SESSION['last_order'] = $code; redirect('/order-confirmed');
        } catch (Throwable $e) { if ($pdo->inTransaction()) $pdo->rollBack(); error_log($e->getMessage()); flash('error', 'تعذر إتمام الطلب. راجع السلة وحاول مجدداً.'); redirect('/cart'); }
    }
    if ($path === 'admin/login') {
        verify_csrf(); $now = time(); $limit = $_SESSION['login_limit'] ?? ['n'=>0,'until'=>0]; if ($limit['until'] > $now) { flash('error', 'محاولات كثيرة. انتظر بضع دقائق ثم حاول مجدداً.'); redirect('/admin'); }
        $email = strtolower(trim((string)($_POST['email'] ?? ''))); $password = (string)($_POST['password'] ?? ''); $stmt = db()->prepare('SELECT id, name, password_hash FROM admins WHERE email = ? AND active = 1'); $stmt->execute([$email]); $admin = $stmt->fetch();
        if ($admin && password_verify($password, $admin['password_hash'])) { session_regenerate_id(true); $_SESSION['admin_id'] = $admin['id']; $_SESSION['admin_name'] = $admin['name']; $_SESSION['login_limit'] = ['n'=>0,'until'=>0]; redirect('/admin/dashboard'); }
        $n = (int)$limit['n'] + 1; $_SESSION['login_limit'] = ['n'=>$n,'until'=>$n >= 5 ? $now + 300 : 0]; flash('error', 'البريد الإلكتروني أو كلمة المرور غير صحيحة.'); redirect('/admin');
    }
    if ($path === 'admin/logout') { verify_csrf(); $_SESSION = []; session_destroy(); redirect('/admin'); }
    if ($path === 'admin/product/save') {
        require_admin(); verify_csrf(); $id = (int)($_POST['id'] ?? 0); $name = trim((string)($_POST['name'] ?? '')); $categoryId = (int)($_POST['category_id'] ?? 0); $price = (float)($_POST['price'] ?? 0); $sale = trim((string)($_POST['sale_price'] ?? '')); $stock = max(0, (int)($_POST['stock'] ?? 0)); $image = trim((string)($_POST['image'] ?? 'assets/images/zoghdan-perfumes.jpg')); $desc = trim((string)($_POST['description'] ?? ''));
        if (mb_strlen($name) < 3 || $categoryId < 1 || $price <= 0 || mb_strlen($desc) < 12 || !preg_match('#^assets/images/[a-z0-9._-]+$#i', $image)) { flash('error', 'أكمل بيانات المنتج وتحقق من صحتها.'); redirect('/admin/products'); }
        $slug = slugify($name); $suffix = 1; while (true) { $q = db()->prepare('SELECT id FROM products WHERE slug = ? AND id != ?'); $q->execute([$slug, $id]); if (!$q->fetch()) break; $slug = slugify($name) . '-' . ++$suffix; }
        if ($id) { $stmt = db()->prepare('UPDATE products SET category_id=?, name=?, slug=?, price=?, sale_price=?, stock=?, image=?, description=? WHERE id=?'); $stmt->execute([$categoryId,$name,$slug,$price,$sale === '' ? null : (float)$sale,$stock,$image,$desc,$id]); }
        else { $stmt = db()->prepare('INSERT INTO products (category_id,name,slug,price,sale_price,stock,image,description,active,featured) VALUES (?,?,?,?,?,?,?,?,1,0)'); $stmt->execute([$categoryId,$name,$slug,$price,$sale === '' ? null : (float)$sale,$stock,$image,$desc]); }
        flash('success', 'تم حفظ بيانات المنتج.'); redirect('/admin/products');
    }
    if ($path === 'admin/product/toggle') { require_admin(); verify_csrf(); $id=(int)($_POST['id']??0); db()->prepare('UPDATE products SET active = 1 - active WHERE id = ?')->execute([$id]); flash('success','تم تغيير حالة نشر المنتج.'); redirect('/admin/products'); }
    if ($path === 'admin/order/status') { require_admin(); verify_csrf(); $status=(string)($_POST['status']??'new'); $allowed=['new','confirmed','packed','shipped','delivered','cancelled']; if (!in_array($status,$allowed,true)) { flash('error','حالة الطلب غير صالحة.'); } else { db()->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$status,(int)($_POST['id']??0)]); flash('success','تم تحديث حالة الطلب.'); } redirect('/admin/orders'); }
    if ($path === 'admin/category/save') { require_admin(); verify_csrf(); $name=trim((string)($_POST['name']??'')); $image=trim((string)($_POST['image']??'assets/images/zoghdan-glass.jpg')); if(mb_strlen($name)<2 || !preg_match('#^assets/images/[a-z0-9._-]+$#i',$image)){flash('error','أدخل اسم القسم واختر صورة صحيحة.');redirect('/admin/categories');} $slug=slugify($name); $suffix=1; while(true){$q=db()->prepare('SELECT id FROM categories WHERE slug=?');$q->execute([$slug]);if(!$q->fetch())break;$slug=slugify($name).'-'.++$suffix;} $sort=(int)db()->query('SELECT COALESCE(MAX(sort_order),0)+1 FROM categories')->fetchColumn(); db()->prepare('INSERT INTO categories(name,slug,image,sort_order,active) VALUES(?,?,?,?,1)')->execute([$name,$slug,$image,$sort]); flash('success','تمت إضافة القسم.'); redirect('/admin/categories'); }
    if ($path === 'admin/settings/save') { require_admin(); verify_csrf(); $name=trim((string)($_POST['store_name']??'')); $phone=trim((string)($_POST['support_phone']??'')); $delivery=(float)($_POST['delivery_charge']??0); $outsideDelivery=(float)($_POST['outside_city_delivery']??0); $currency=trim((string)($_POST['currency_symbol']??'ج.م'));$newPassword=(string)($_POST['new_password']??''); if(mb_strlen($name)<2 || mb_strlen($phone)<8 || $delivery<0 || $outsideDelivery<0){flash('error','أدخل اسم المتجر ورقم خدمة العملاء ورسوم التوصيل.');redirect('/admin/settings');} if($newPassword!=='' && strlen($newPassword)<12){flash('error','يجب ألا تقل كلمة المرور الجديدة عن 12 حرفاً.');redirect('/admin/settings');} $save=db()->prepare('INSERT INTO settings(setting_key,setting_value) VALUES (?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)'); if(!in_array($currency,['ج.م','ر.س','د.إ','$'],true))$currency='ج.م'; foreach(['store_name'=>$name,'support_phone'=>$phone,'delivery_charge'=>(string)$delivery,'outside_city_delivery'=>(string)$outsideDelivery,'currency_symbol'=>$currency] as $key=>$value)$save->execute([$key,$value]); if($newPassword!=='')db()->prepare('UPDATE admins SET password_hash=? WHERE id=?')->execute([password_hash($newPassword,PASSWORD_DEFAULT),(int)$_SESSION['admin_id']]); flash('success',$newPassword!=='' ? 'تم حفظ الإعدادات وكلمة مرور المدير.' : 'تم حفظ إعدادات المتجر.'); redirect('/admin/settings'); }
    http_response_code(404); exit('Not found');
}

if ($path === '') {
    require __DIR__ . '/home.php';
    exit;
}

if ($path === 'shop') { $pdo=db(); $cats=$pdo->query('SELECT * FROM categories WHERE active=1 ORDER BY sort_order')->fetchAll(); $q=trim((string)($_GET['q']??'')); $catSlug=trim((string)($_GET['category']??'')); $where=['p.active=1']; $args=[]; if($q!==''){$where[]='(p.name LIKE ? OR p.description LIKE ?)';$args[]='%'.$q.'%';$args[]='%'.$q.'%';} if($catSlug!==''){$where[]='c.slug=?';$args[]=$catSlug;} $stmt=$pdo->prepare('SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id WHERE '.implode(' AND ',$where).' ORDER BY p.featured DESC,p.id DESC');$stmt->execute($args);$products=$stmt->fetchAll(); header_html('المتجر'); ?>
