if ($path === 'track-order') { $code=trim((string)($_GET['code']??'')); $phone=trim((string)($_GET['phone']??'')); $order=null; if($code!==''&&$phone!==''){ $stmt=db()->prepare('SELECT order_code,status,total,created_at FROM orders WHERE order_code=? AND phone=? LIMIT 1');$stmt->execute([$code,$phone]);$order=$stmt->fetch(); } header_html('تتبّع الطلب'); ?><section class="info-page"><p class="eyebrow"><i></i> حالة الطلب</p><h1>تتبّع طلبك</h1><p class="info-lead">أدخل رقم الطلب ورقم الهاتف المستخدم عند إتمامه لمعرفة حالته.</p><form class="checkout-form track-form" method="get" action="/track-order"><label>رقم الطلب<input name="code" value="<?=e($code)?>" placeholder="ZG-000000-ABC" required></label><label>رقم الهاتف<input name="phone" value="<?=e($phone)?>" placeholder="أدخل رقم الهاتف" required></label><button class="button button-vermilion">تتبّع الطلب <span>→</span></button></form><?php if($code!==''&&$phone!==''):?><article class="info-card track-result"><?php if($order):?><h2>الطلب <?=e($order['order_code'])?></h2><p>الحالة: <b><?=e(order_status_label($order['status']))?></b> · الإجمالي: <b><?=money((float)$order['total'])?></b></p><?php else:?><h2>لم نعثر على الطلب</h2><p>تحقق من رقم الطلب ورقم الهاتف وحاول مجدداً.</p><?php endif;?></article><?php endif;?></section><?php footer_html();exit; }

if ($path === 'admin') {
    if (is_admin()) redirect('/admin/dashboard');
    header_html('دخول المدير', true); ?>
    <section class="admin-login"><a class="brand" href="/"><img src="/assets/images/zoghdan-mark.svg" alt=""><span class="brand-lockup"><strong>Zoghdan</strong><small>زغدان</small></span></a><div><p class="eyebrow"><i></i> لوحة الإدارة</p><h1>تسجيل دخول المدير</h1><form method="post" action="/admin/login"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>البريد الإلكتروني<input name="email" type="email" autocomplete="username" required></label><label>كلمة المرور<input name="password" type="password" autocomplete="current-password" required></label><button class="button button-vermilion">دخول آمن <span>←</span></button></form></div></section><?php footer_html(); exit;
}

if ($path === 'admin/settings') { require_admin(); require __DIR__ . '/admin_settings.php'; exit; }
if ($path === 'admin/categories') { require_admin(); require __DIR__ . '/admin_categories.php'; exit; }

if (str_starts_with($path, 'admin/')) {
    require_admin();
    $section = substr($path, 6);
    $pdo = db();
    $statusLabels = ['new'=>'جديد', 'confirmed'=>'تم التأكيد', 'packed'=>'قيد التجهيز', 'shipped'=>'تم الشحن', 'delivered'=>'تم التسليم', 'cancelled'=>'ملغي'];
    header_html('إدارة زغدان', true); ?>
    <div class="admin-shell">
      <aside class="admin-side"><a class="brand" href="/"><img src="/assets/images/zoghdan-mark.svg" alt=""><span class="brand-lockup"><strong>Zoghdan</strong><small>زغدان</small></span></a><p>إدارة المتجر</p><a class="<?= $section==='dashboard'?'active':'' ?>" href="/admin/dashboard">نظرة عامة</a><a class="<?= $section==='products'?'active':'' ?>" href="/admin/products">المنتجات</a><a href="/admin/categories">الأقسام</a><a class="<?= $section==='orders'?'active':'' ?>" href="/admin/orders">الطلبات</a><a href="/admin/settings">الإعدادات</a><form method="post" action="/admin/logout"><input type="hidden" name="csrf" value="<?=csrf()?>"><button>تسجيل الخروج</button></form></aside>
      <section class="admin-content">
      <?php if ($section === 'dashboard') {
        $metrics = $pdo->query("SELECT COUNT(*) orders, COALESCE(SUM(total),0) revenue, SUM(status='new') new_orders FROM orders")->fetch();
        $latest = $pdo->query('SELECT * FROM orders ORDER BY id DESC LIMIT 7')->fetchAll(); ?>
        <p class="eyebrow"><i></i> نظرة عامة على المتجر</p><h1>أهلاً، <?=e($_SESSION['admin_name'] ?? 'مدير زغدان')?>.</h1>
        <div class="metric-grid"><div><small>إجمالي الطلبات</small><b><?= (int)$metrics['orders']?></b></div><div><small>إجمالي المبيعات المسجلة</small><b><?=money((float)$metrics['revenue'])?></b></div><div><small>طلبات جديدة</small><b><?= (int)$metrics['new_orders']?></b></div></div>
        <div class="admin-panel"><div class="panel-head"><h2>أحدث الطلبات</h2><a href="/admin/orders">عرض الكل ←</a></div><?php if (!$latest): ?><p class="empty">لا توجد طلبات بعد.</p><?php else: ?><table><thead><tr><th>رقم الطلب</th><th>العميل</th><th>الإجمالي</th><th>الحالة</th></tr></thead><tbody><?php foreach ($latest as $o): ?><tr><td><?=e($o['order_code'])?></td><td><?=e($o['customer_name'])?></td><td><?=money((float)$o['total'])?></td><td><span class="status <?=e($o['status'])?>"><?=e($statusLabels[$o['status']] ?? $o['status'])?></span></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></div>
      <?php } elseif ($section === 'products') {
        $cats = $pdo->query('SELECT * FROM categories WHERE active=1 ORDER BY sort_order')->fetchAll();
        $items = $pdo->query('SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC')->fetchAll(); ?>
        <div class="admin-title"><div><p class="eyebrow"><i></i> إدارة المجموعة</p><h1>منتجات زغدان.</h1></div><button class="button button-dark" data-modal-open="product-modal">إضافة منتج <span>+</span></button></div>
        <div class="admin-panel"><table><thead><tr><th>المنتج</th><th>القسم</th><th>السعر</th><th>المخزون</th><th>الحالة</th><th>إجراءات</th></tr></thead><tbody><?php foreach ($items as $p): $productData=['id'=>(int)$p['id'],'name'=>$p['name'],'category_id'=>(int)$p['category_id'],'price'=>$p['price'],'sale_price'=>$p['sale_price'],'stock'=>(int)$p['stock'],'image'=>$p['image'],'description'=>$p['description']]; ?><tr><td class="admin-product"><img src="/<?=e($p['image'])?>" alt=""><b><?=e($p['name'])?></b></td><td><?=e($p['category_name'])?></td><td><?=money((float)($p['sale_price'] ?? $p['price']))?></td><td><?= (int)$p['stock']?></td><td><span class="status <?= $p['active']?'delivered':'cancelled' ?>"><?= $p['active']?'منشور':'مخفي' ?></span></td><td class="admin-actions"><button type="button" class="table-action" data-product-edit="<?=e(json_encode($productData, JSON_UNESCAPED_UNICODE | JSON_HEX_APOS | JSON_HEX_QUOT))?>">تعديل</button><form method="post" action="/admin/product/toggle"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?= (int)$p['id']?>"><button class="table-action"><?= $p['active']?'إخفاء':'نشر' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div>
        <dialog id="product-modal" class="modal"><form method="post" action="/admin/product/save" class="product-form"><div class="modal-head"><h2>إضافة منتج</h2><button type="button" data-modal-close aria-label="إغلاق">×</button></div><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value=""><label>اسم المنتج<input name="name" required minlength="3"></label><label>القسم<select name="category_id" required><?php foreach ($cats as $c): ?><option value="<?= (int)$c['id']?>"><?=e($c['name'])?></option><?php endforeach; ?></select></label><div class="field-row"><label>السعر<input name="price" type="number" min="0.01" step="0.01" required></label><label>سعر العرض <small>(اختياري)</small><input name="sale_price" type="number" min="0.01" step="0.01"></label><label>المخزون<input name="stock" type="number" min="0" required></label></div><label>صورة المنتج<select name="image"><option value="assets/images/zoghdan-perfumes.jpg">العطور</option><option value="assets/images/zoghdan-incense.jpg">البخور والعود</option><option value="assets/images/zoghdan-glass.jpg">الزجاجيات</option></select></label><label>وصف المنتج<textarea name="description" rows="4" required minlength="12"></textarea></label><button class="button button-vermilion">حفظ المنتج <span>←</span></button></form></dialog>
      <?php } elseif ($section === 'orders') {
        $orders = $pdo->query('SELECT * FROM orders ORDER BY id DESC')->fetchAll(); ?>
        <div class="admin-title"><div><p class="eyebrow"><i></i> متابعة الطلبات</p><h1>طلبات العملاء.</h1></div></div><div class="admin-panel"><table><thead><tr><th>رقم الطلب</th><th>العميل والعنوان</th><th>الهاتف</th><th>الإجمالي</th><th>الحالة</th><th>تحديث الحالة</th></tr></thead><tbody><?php foreach ($orders as $o): ?><tr><td><b><?=e($o['order_code'])?></b><small><?=e(date('d/m/Y',strtotime($o['created_at'])))?></small></td><td><?=e($o['customer_name'])?><small><?=e($o['address'])?></small></td><td><?=e($o['phone'])?></td><td><?=money((float)$o['total'])?></td><td><span class="status <?=e($o['status'])?>"><?=e($statusLabels[$o['status']] ?? $o['status'])?></span></td><td><form method="post" action="/admin/order/status" class="status-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?= (int)$o['id']?>"><select name="status"><?php foreach ($statusLabels as $key=>$label): ?><option value="<?=e($key)?>" <?= $o['status']===$key?'selected':''?>><?=e($label)?></option><?php endforeach; ?></select><button>حفظ</button></form></td></tr><?php endforeach; ?></tbody></table></div>
      <?php } else { http_response_code(404); echo '<p>الصفحة غير موجودة.</p>'; } ?>
      </section>
    </div><?php footer_html(); exit;
}

http_response_code(404); header_html('الصفحة غير موجودة'); echo '<section class="empty-page"><h1>الصفحة غير موجودة.</h1><a class="button button-dark" href="/">العودة للرئيسية</a></section>'; footer_html();
